"""Independent reference model for the layered receive/canonical-wire contract."""
import hashlib, json

MAX62=(1<<62)-1
MAXSTREAMS=1<<60
LEVELS=['I','H','A']
EMPTY=b''

def venc(x,width=None):
    if width is None: width=next(w for w in (1,2,4,8) if x<2**(8*w-2))
    assert 0<=x<2**(8*width-2)
    return (([1,2,4,8].index(width)<<(8*width-2))|x).to_bytes(width,'big')

class Err(Exception):
    def __init__(self,code,offset): self.code=code; self.offset=offset

# ---------------------------------------------------------------- varint reader
class Rd:
    def __init__(self,d,p,fs): self.d=d; self.p=p; self.fs=fs
    def vi(self):
        if self.p>=len(self.d): raise Err('FRAME_ENCODING_ERROR',self.fs)
        b=self.d[self.p]; self.p+=1
        w=1<<(b>>6)
        if w-1>len(self.d)-self.p: raise Err('FRAME_ENCODING_ERROR',self.fs)
        val=b&0x3f
        for i in range(1,w): val=(val<<8)|self.d[self.p+i]
        self.p+=w-1
        return val
    def one(self):
        if self.p>=len(self.d): raise Err('FRAME_ENCODING_ERROR',self.fs)
        b=self.d[self.p]; self.p+=1; return b
    def take(self,n):
        if n<0 or n>len(self.d)-self.p: raise Err('FRAME_ENCODING_ERROR',self.fs)
        r=self.d[self.p:self.p+n]; self.p+=n; return r
    def rest(self): return self.take(len(self.d)-self.p)

KNOWN=set([0x00,0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08,0x09,0x0a,0x0b,0x0c,0x0d,0x0e,0x0f,
           0x10,0x11,0x12,0x13,0x14,0x15,0x16,0x17,0x18,0x19,0x1a,0x1b,0x1c,0x1d,0x1e,0x30,0x31])
APPONLY=set([0x04,0x05,0x08,0x09,0x0a,0x0b,0x0c,0x0d,0x0e,0x0f,0x10,0x11,0x12,0x13,0x14,0x15,
             0x16,0x17,0x18,0x19,0x1a,0x1b,0x1d,0x30,0x31])

class Frame:
    pass

def parse_frame(d,p,level):
    fs=p
    b0=d[p]; w=1<<(b0>>6)
    if w>len(d)-p: raise Err('FRAME_ENCODING_ERROR',fs)
    t=b0&0x3f
    for i in range(1,w): t=(t<<8)|d[p+i]
    if w!=1 or t not in KNOWN: raise Err('FRAME_ENCODING_ERROR',fs)
    if t in (0x07,0x1e): raise Err('PROTOCOL_VIOLATION',fs)
    if level!=2 and t in APPONLY: raise Err('PROTOCOL_VIOLATION',fs)
    f=Frame(); f.type=t
    c=Rd(d,p+w,fs)
    if t in (0x00,0x01): pass
    elif t in (0x02,0x03):
        f.largest=c.vi(); f.delay=c.vi(); f.count=c.vi(); f.first=c.vi()
        if f.first>f.largest: raise Err('FRAME_ENCODING_ERROR',fs)
        low=f.largest-f.first
        f.pairs=[]
        for _ in range(f.count):
            gap=c.vi(); rng=c.vi()
            if low<gap+2: raise Err('FRAME_ENCODING_ERROR',fs)
            high=low-gap-2
            if rng>high: raise Err('FRAME_ENCODING_ERROR',fs)
            f.pairs.append((gap,rng)); low=high-rng
        if t==0x03: f.ecn=(c.vi(),c.vi(),c.vi())
    elif t==0x04: f.sid=c.vi(); f.err=c.vi(); f.final=c.vi()
    elif t==0x05: f.sid=c.vi(); f.err=c.vi()
    elif t==0x06:
        f.off=c.vi(); f.ln=c.vi(); f.data=c.take(f.ln)
        if f.off+f.ln>MAX62: raise Err('FRAME_ENCODING_ERROR',fs)
    elif 0x08<=t<=0x0f:
        f.off_flag=bool(t&4); f.len_flag=bool(t&2); f.fin=bool(t&1)
        f.sid=c.vi(); f.off=c.vi() if f.off_flag else 0
        if f.len_flag: f.ln=c.vi(); f.data=c.take(f.ln)
        else: f.data=c.rest(); f.ln=len(f.data)
    elif t in (0x10,0x12,0x13,0x14,0x16,0x17,0x19):
        f.v=c.vi()
        if t in (0x12,0x13,0x16,0x17) and f.v>MAXSTREAMS: raise Err('FRAME_ENCODING_ERROR',fs)
    elif t in (0x11,0x15): f.sid=c.vi(); f.v=c.vi()
    elif t==0x18:
        f.seq=c.vi(); f.rpt=c.vi()
        if f.rpt>f.seq: raise Err('FRAME_ENCODING_ERROR',fs)
        f.cidlen=c.one()
        if f.cidlen<1 or f.cidlen>20: raise Err('FRAME_ENCODING_ERROR',fs)
        f.cid=c.take(f.cidlen); f.token=c.take(16)
    elif t in (0x1a,0x1b): f.data=c.take(8)
    elif t==0x1c: f.err=c.vi(); f.trig=c.vi(); f.rlen=c.vi(); f.data=c.take(f.rlen)
    elif t==0x1d: f.err=c.vi(); f.rlen=c.vi(); f.data=c.take(f.rlen)
    elif t==0x30: f.data=c.rest()
    elif t==0x31: f.ln=c.vi(); f.data=c.take(f.ln)
    f.end=c.p
    return f

def encode_frame(f):
    t=f.type
    if t==0x00: return b'\x00'
    if t==0x01: return b'\x01'
    if t in (0x02,0x03):
        out=venc(t)+venc(f.largest)+venc(f.delay)+venc(f.count)+venc(f.first)
        for g,r in f.pairs: out+=venc(g)+venc(r)
        if t==0x03: out+=venc(f.ecn[0])+venc(f.ecn[1])+venc(f.ecn[2])
        return out
    if t==0x04: return venc(4)+venc(f.sid)+venc(f.err)+venc(f.final)
    if t==0x05: return venc(5)+venc(f.sid)+venc(f.err)
    if t==0x06: return venc(6)+venc(f.off)+venc(f.ln)+f.data
    if 0x08<=t<=0x0f:
        out=venc(t)+venc(f.sid)
        if f.off_flag: out+=venc(f.off)
        if f.len_flag: out+=venc(f.ln)
        return out+f.data
    if t==0x10: return venc(0x10)+venc(f.v)
    if t in (0x11,0x15): return venc(t)+venc(f.sid)+venc(f.v)
    if t in (0x12,0x13,0x16,0x17,0x19): return venc(t)+venc(f.v)
    if t==0x14: return venc(0x14)+venc(f.v)
    if t==0x18: return venc(0x18)+venc(f.seq)+venc(f.rpt)+bytes([f.cidlen])+f.cid+f.token
    if t in (0x1a,0x1b): return venc(t)+f.data
    if t==0x1c: return venc(0x1c)+venc(f.err)+venc(f.trig)+venc(f.rlen)+f.data
    if t==0x1d: return venc(0x1d)+venc(f.err)+venc(f.rlen)+f.data
    if t==0x30: return b'\x30'+f.data
    if t==0x31: return venc(0x31)+venc(f.ln)+f.data
    raise AssertionError

# ---------------------------------------------------------------- byte store
class Store:
    def __init__(self): self.segs=[]   # list of (start, bytes) sorted, disjoint
    def insert(self,lo,data,fs):
        if not data: return
        hi=lo+len(data)
        overlap=[s for s in self.segs if s[0]<hi and s[0]+len(s[1])>lo]
        for st,b in overlap:
            a=max(st,lo); bnd=min(st+len(b),hi)
            for p in range(a,bnd):
                if b[p-st]!=data[p-lo]: raise Err('PROTOCOL_VIOLATION',fs)
        added=[]; cur=lo
        for st,b in overlap:
            if st>cur: added.append((cur,data[cur-lo:st-lo]))
            cur=max(cur,st+len(b))
        if cur<hi: added.append((cur,data[cur-lo:]))
        self.segs=sorted(self.segs+added)
    def merged(self):
        out=[]
        for st,b in self.segs:
            if out and st<=out[-1][1]: out[-1][1]=max(out[-1][1],st+len(b))
            else: out.append([st,st+len(b)])
        return out
    def unique(self): return sum(len(b) for _,b in self.segs)
    def prefix(self):
        m=self.merged()
        return m[0][1] if m and m[0][0]==0 else 0
    def prefix_bytes(self):
        p=self.prefix(); out=bytearray()
        for st,b in self.segs:
            if st>=p: break
            out+=b
        return bytes(out[:p])

class Stream:
    def __init__(self,sid): self.id=sid; self.high=0; self.sendmax=0; self.final=None; self.reset=None; self.stop=None; self.bytes=Store()

class Trace:
    def __init__(self,tr):
        self.lim_conn=tr['limits']['connection']; self.lim_stream=tr['limits']['stream']
        self.lim_bidi=tr['limits']['bidi']; self.lim_uni=tr['limits']['uni']; self.lim_cids=tr['limits']['cids']
        self.local_bidi=tr['local']['bidi']; self.local_uni=tr['local']['uni']
        self.local=tr['local']['cids']; self.cidw=len(bytes.fromhex(self.local[0]))
        self.peer=tr['peer']['cid']; self.peertok=tr['peer']['token']
        self.seeds=tr['received']
        self.events=tr['events']
        self.keys={'I':True,'H':False,'A':False}
        self.closed=None
        self.largest={'I':None,'H':None,'A':None}
        self.seen={'I':set(),'H':set(),'A':set()}
        self.ack={'I':[],'H':[],'A':[]}
        self.ecn={'I':[0,0,0],'H':[0,0,0],'A':[0,0,0]}
        self.crypto={'I':Store(),'H':Store(),'A':Store()}
        self.streams={}
        self.open_bidi=0; self.open_uni=0; self.used=0
        self.smd=0; self.sms=[0,0]
        self.peermap={0:(self.peer,self.peertok)}
        self.rpt=0; self.active=1
        self.retired=set()
        self.epochs={}
        self.cur=0
        if self.seeds['A'] is not None:
            self.epochs[0]=[self.seeds['A'],self.seeds['A'],1]
        for l in LEVELS:
            if self.seeds[l] is not None:
                self.seen[l].add(self.seeds[l]); self.largest[l]=self.seeds[l]
        self.snapshot=None
        self.packets=[]; self.datagrams=[]

    # ---------------- snapshot / rollback
    def snap(self):
        return (dict(self.keys),self.closed,dict(self.largest),{k:set(v) for k,v in self.seen.items()},
                {k:list(v) for k,v in self.ack.items()},{k:list(v) for k,v in self.ecn.items()},
                {k:Store() for k in LEVELS}, {sid:(s.high,s.sendmax,s.final,s.reset,s.stop,s.bytes.merged(),s.bytes.segs[:]) for sid,s in self.streams.items()},
                self.open_bidi,self.open_uni,self.used,self.smd,list(self.sms),
                {k:v for k,v in self.peermap.items()},self.rpt,self.active,set(self.retired),
                {k:list(v) for k,v in self.epochs.items()},self.cur)
    def restore(self,s):
        (self.keys,self.closed,self.largest,self.seen,self.ack,self.ecn,_,streams, self.open_bidi,self.open_uni,self.used,
         self.smd,self.sms,self.peermap,self.rpt,self.active,self.retired,self.epochs,self.cur)=s
        self.streams={}
        for sid,(high,sendmax,fin,rst,stp,_,segs) in streams.items():
            s2=Stream(sid); s2.high=high; s2.sendmax=sendmax; s2.final=fin; s2.reset=rst; s2.stop=stp; s2.bytes.segs=list(segs)
            self.streams[sid]=s2
    # note: crypto stores are snapshotted separately
PYEOF
